use std::collections::BTreeMap;
use std::io::*;

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    let mut m: BTreeMap<String, i64> = BTreeMap::new();
    let mut out = String::new();
    for line in s.lines() {
        let t: Vec<&str> = line.split_whitespace().collect();
        if t.is_empty() {
            continue;
        }
        let amt = |i: usize| -> i64 { t.get(i).and_then(|x| x.parse::<i64>().ok()).unwrap_or(0) };
        let r: String = match t[0] {
            "open" => {
                let a = amt(2);
                if a < 0 {
                    "error: invalid amount".into()
                } else if m.contains_key(t[1]) {
                    "error: duplicate account".into()
                } else {
                    m.insert(t[1].to_string(), a);
                    "ok".into()
                }
            }
            "deposit" | "withdraw" => {
                let a = amt(2);
                if a <= 0 {
                    "error: invalid amount".into()
                } else if !m.contains_key(t[1]) {
                    format!("error: unknown account {}", t[1])
                } else {
                    let b = m.get_mut(t[1]).unwrap();
                    if t[0] == "deposit" {
                        *b += a;
                        "ok".into()
                    } else if *b < a {
                        "error: insufficient funds".into()
                    } else {
                        *b -= a;
                        "ok".into()
                    }
                }
            }
            "transfer" => {
                let a = amt(3);
                if a <= 0 {
                    "error: invalid amount".into()
                } else if !m.contains_key(t[1]) {
                    format!("error: unknown account {}", t[1])
                } else if !m.contains_key(t[2]) {
                    format!("error: unknown account {}", t[2])
                } else if t[1] == t[2] {
                    "error: same account".into()
                } else if m[t[1]] < a {
                    "error: insufficient funds".into()
                } else {
                    *m.get_mut(t[1]).unwrap() -= a;
                    *m.get_mut(t[2]).unwrap() += a;
                    "ok".into()
                }
            }
            "balance" => match m.get(t[1]) {
                Some(b) => b.to_string(),
                None => format!("error: unknown account {}", t[1]),
            },
            _ => continue,
        };
        out.push_str(&r);
        out.push('\n');
    }
    for (k, v) in &m {
        out.push_str(&format!("{} {}\n", k, v));
    }
    print!("{}", out);
}

